import {ROLES,LIMIT,seed,transact,round} from './core.js';
const source=await fetch('./source-data.json').then(r=>r.json());
const KEY='gc-operations-prototype-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=null;}catch{}state=state||seed(source);
transact(state,'initialiseIssues');
let page='overview',jobId='',inventoryTab='stock',query='',filter='All',menu=false;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:3});
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:0});
const icon=(name)=>{const d={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',jobs:'M8 4h12v17H4V4h4 M9 2h6v4H9z M8 11h8 M8 15h6',stock:'m3 7 9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10',receiving:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',waste:'M5 7h14l-1 14H6z M3 7h18 M9 7V3h6v4 M10 11v6 M14 11v6',quality:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z m-5 10 3 3 6-6',finance:'M3 6h18v14H3z M3 10h18 M15 15h3 M7 3h10',trace:'M3 5h5v5H3z M16 14h5v5h-5z M3 15h5v5H3z M8 7h5v10h3 M8 17h5',approvals:'m4 12 5 5L20 6',audit:'M4 4h16v17H4z M8 9h8 M8 13h8 M8 17h5',blueprint:'M3 3h7c2 0 2 2 2 2s0-2 2-2h7v17h-7c-2 0-2 2-2 2s0-2-2-2H3z M12 5v17',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d[name]||d.stock}"/></svg>`};
const pill=(t,c)=>`<span class="pill ${c||(/Released|Completed|Closed|Posted|Approved|Resolved/.test(t)?'green':/Rejected|Expired|discrepancy|Incident/.test(t)?'red':/hold|Hold|Pending|Awaiting|Recount/.test(t)?'amber':'blue')}">${esc(t)}</span>`;
const btn=(label,action,id='',secondary=false)=>`<button class="btn ${secondary?'secondary ':''}small" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const heading=(eyebrow,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtle">${desc}</p></div><div class="actions">${actions}</div></div>`;
const card=(title,body,right='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${right}</div>${body}</section>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${heads.length}" class="empty">No records in this view.</td></tr>`}</tbody></table></div>`;
const kpi=(label,value,note)=>`<div class="kpi"><div class="kpi-label">${label}<span>↗</span></div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></div>`;
const byEntity=xs=>state.branch==='All entities'?xs:xs.filter(x=>x.entity===state.branch);
const material=id=>source.Material_Master.find(x=>x.Material_ID===id);
const stockStatus=l=>l.countHold?'Count discrepancy hold':l.recall?'Incident hold':l.expiry&&l.expiry<='2026-10-24'?'Expired':!l.expiry?'Missing expiry':l.hold?l.quality:'Released';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage unavailable; export your review before closing.');}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function navigate(p,id=''){page=p;jobId=id;query='';filter='All';menu=false;render();window.scrollTo(0,0);}
function run(action,p={}){try{const next=structuredClone(state);transact(next,action,p);state=next;save();closeModal();render();toast('Saved in this demonstration workspace.');return true;}catch(e){const err=$('#form-error');if(err)err.textContent=e.message;else toast(e.message);return false;}}
function shell(body){const items=[['overview','Overview'],['jobs','Job cards'],['issues','MRS & GIN'],['stock','Inventory'],['receiving','Receipts & transfers'],['waste','Waste bank'],['quality','Quality & holds'],['finance','Supplier accounts'],['trace','Dispatch & traceability'],['approvals','Approval desk'],['audit','Activity & notifications'],['blueprint','Blueprint & demo guide']];return `<div class="shell"><div class="mobile-backdrop ${menu?'show':''}" data-action="menu"></div><aside class="sidebar ${menu?'open':''}"><div class="brand"><div class="brandmark">g</div><div><strong>Goldsmith<br>& Chocosmith</strong><small>OPERATIONS</small></div></div><div class="nav-label">WORKSPACE</div>${items.slice(0,9).map(([p,t])=>`<button class="nav ${page===p?'active':''}" data-page="${p}">${icon(p)}${t}</button>`).join('')}<div class="nav-label">CONTROL CENTRE</div>${items.slice(9).map(([p,t])=>`<button class="nav ${page===p?'active':''}" data-page="${p}">${icon(p)}${t}</button>`).join('')}<div class="sidebar-foot"><b>Two businesses. One clear view.</b>Prototype workspace<br><span class="inline-note" style="color:#a8bba8">Browser-local demonstration</span></div></aside><main class="main"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Toggle navigation">☰</button><div class="crumb">Workspace <span style="padding:0 8px">/</span> ${items.find(x=>x[0]===page)?.[1]||'Overview'}</div><div class="top-tools"><select id="branch" class="branch" aria-label="Entity filter">${['All entities','Goldsmith','Chocosmith'].map(r=>`<option ${state.branch===r?'selected':''}>${r}</option>`).join('')}</select><button class="toolbar-icon" data-page="audit" aria-label="Open notifications">${icon('bell')}<span class="count">${state.notifications.length}</span></button><select id="role" aria-label="Demonstration role">${ROLES.map(r=>`<option ${state.role===r?'selected':''}>${r}</option>`).join('')}</select><div class="avatar">${state.role.split(' ').map(x=>x[0]).join('')}</div></div></header><div class="notice"><span>DEMONSTRATION · Example operating data · No live bank payments or emails</span><span>Workbook catalogue + illustrative workflows</span></div><div class="content">${body}<div class="footer-note"><span>Goldsmith & Chocosmith · Operations prototype 1.1</span><span>Scenario date: 24 October 2026 · Saved on this browser</span></div></div></main></div>`;}
function overview(){const jobs=byEntity(state.jobs),lots=byEntity(state.lots),open=jobs.filter(x=>!x.closed);const out=jobs.reduce((a,j)=>a+j.output,0),plan=jobs.reduce((a,j)=>a+j.planned,0);return heading('OPERATIONS / 24 OCTOBER 2026','A clear view of the floor.','Production, stock and exceptions. Together in one place.',`<button class="btn secondary" data-action="walkthrough">Start walkthrough ↗</button><button class="btn" data-page="jobs">View job cards →</button>`)+`<div class="kpis">${kpi('Active job cards',open.length,'Across the selected entities')}${kpi('Finished output recorded',n(out)+' <span style="font-size:15px">kg</span>',n(plan)+' kg planned across these example JCs')}${kpi('Lots requiring attention',lots.filter(l=>stockStatus(l)!=='Released').length,'Inspection, expiry or exception holds')}${kpi('Requests awaiting approval',state.requests.filter(r=>r.status==='Pending').length+state.payments.filter(p=>p.status==='Pending approval').length,'Across both entities')}</div><div class="grid-two"><div>${card('Production in progress',table(['Job card / product','Stage','Completion','Status'],open.map(j=>`<tr><td><button class="link" data-job="${j.id}">${j.id}</button><br><span class="subtle">${j.product} · ${j.entity}</span></td><td>${j.stage}</td><td>${n(j.output)} / ${n(j.planned)} kg<div class="progress"><i style="width:${Math.min(100,j.output/j.planned*100)}%"></i></div></td><td>${pill(j.status)}</td></tr>`)),`<button class="link" data-page="jobs">All job cards ↗</button>`)}${card('Output by job card',`<div class="card-body"><div class="subtle">Actual finished output against planned quantity · kg</div><div class="chart">${jobs.map(j=>`<div class="bar-group" title="${j.id}: ${j.output} of ${j.planned} kg"><div class="bar pale" style="height:${Math.max(4,j.planned/1200*120)}px"></div><div class="bar" style="height:${Math.max(3,j.output/1200*120)}px"></div><span>${j.id.slice(-3)}</span></div>`).join('')}</div><div class="legend"><span><i class="dot pale"></i>Planned</span><span><i class="dot"></i>Finished output</span></div></div>`)}</div><div>${card('Needs your attention',`<div class="card-body"><div class="alert-row"><div class="alert-icon">!</div><div><div class="alert-title">Quality release pending</div><p class="alert-desc">${lots.filter(l=>l.quality==='Awaiting inspection').length} lots remain unavailable until inspection.</p><button class="link" data-page="quality">Review inspection queue →</button></div></div><div class="alert-row"><div class="alert-icon">↔</div><div><div class="alert-title">Waste receipt difference</div><p class="alert-desc">WB-002: 8 kg sent, 7.5 kg received. Store manager investigation.</p><button class="link" data-page="waste">Open waste bank →</button></div></div><div class="alert-row"><div class="alert-icon">◷</div><div><div class="alert-title">Source transfers need reconciliation</div><p class="alert-desc">2 workbook transfers have no matching transfer entries in the supplied ledger.</p><button class="link" data-action="sourceTransfers">Inspect source records →</button></div></div></div>`)}${card('Recent activity',`<div class="card-body">${state.audit.slice(0,4).map(a=>`<div class="activity"><div class="activity-dot"></div><div><p>${esc(a.action)}</p><small>${esc(a.ref)} · ${esc(a.role)}</small></div></div>`).join('')}</div>`)}<div class="info">The 36 material records and six original locations come from your workbook. Operating lots, users, recipes and transactions shown here are hypothetical examples.</div></div></div>`;}
function jobsPage(){if(jobId)return jobDetail(state.jobs.find(j=>j.id===jobId));const jobs=byEntity(state.jobs).filter(j=>(filter==='All'||j.status===filter)&&(!query||(j.id+' '+j.product).toLowerCase().includes(query.toLowerCase())));return heading('PRODUCTION','Every job. Every stage.','Partial output, material movement and exceptions stay with the respective job card.',`<button class="btn" data-action="output">+ Record output</button>`)+`<div class="filters"><input class="search" id="query" placeholder="Search job card or product" value="${esc(query)}" aria-label="Search job cards"><select id="filter" aria-label="Filter job status">${['All','In progress','Released','Closed'].map(x=>`<option ${x===filter?'selected':''}>${x}</option>`).join('')}</select></div>`+card('Job card register',table(['Job card','Product / entity','Planned','Actual finished','Remaining','Stage','Status'],jobs.map(j=>`<tr><td><button class="link" data-job="${j.id}">${j.id}</button><div class="inline-note">Due ${j.due}</div></td><td>${j.product}<div class="subtle">${j.entity}</div></td><td>${n(j.planned)} kg</td><td>${n(j.output)} kg</td><td>${n(Math.max(0,j.planned-j.output))} kg${j.output>j.planned?'<div class="pill amber">Overproduction</div>':''}</td><td>${j.stage}</td><td>${pill(j.status)}</td></tr>`)));}
function jobDetail(j){if(!j)return '<p>Job card not found.</p>';const extra=state.requests.filter(r=>r.job===j.id);const accounted=j.consumed+j.returned+j.waste+j.loss;return `<button class="link back" data-page="jobs">← All job cards</button>`+heading('JOB CARD / '+j.entity.toUpperCase(),j.id,j.product+' · '+j.recipe,`${pill(j.status)}<button class="btn secondary" data-action="mrsCreate" data-id="${j.id}">Create MRS</button><button class="btn secondary" data-action="extra" data-id="${j.id}">Request extra material</button><button class="btn" data-action="output" data-id="${j.id}">+ Record output</button>`)+`<div class="kpis">${kpi('Planned finished output',n(j.planned)+' kg','Original approved target')}${kpi('Actual finished output',n(j.output)+' kg',n(Math.max(0,j.planned-j.output))+' kg remaining')}${kpi('Total material issued',n(j.issued)+' kg','Issues are not the same as consumption')}${kpi('Input quantity explained',n(accounted)+' kg',n(round(j.issued-accounted))+' kg still in production / unresolved')}</div><div class="grid-two"><div>${jobIssuesSection(j)}${card('Stage-wise production',`<div class="card-body">${['Weighing & issue','Mixing / processing','Moulding','Packing','Quality release'].map((s,i)=>`<div class="stage"><div class="stage-num">${i+1}</div><div class="stage-main"><b>${s}</b><div class="subtle">${i===0?n(j.issued)+' kg issued':i===3?n(j.output)+' kg finished output recorded':i===4?'Quality decision remains separate from JC closure':'Actual stage transactions retained on this JC'}</div></div>${pill(i<2&&j.output?'Recorded':i===3&&j.output?'Partial':'Stage review',i<2&&j.output?'green':'')}</div>`).join('')}</div>`)}${card('Output entries',table(['Reference','Stage / batch','Quantity','Stock state'],j.entries.map(e=>{const l=state.lots.find(x=>x.id===e.lot);return `<tr><td>${e.id}<div class="inline-note">${e.time}</div></td><td>${e.stage}<br><span class="code">${e.lot}</span></td><td>${n(e.qty)} kg</td><td>${l?pill(stockStatus(l)):pill('Historical')}</td></tr>`})),`<button class="link" data-page="quality">Quality queue ↗</button>`)}${card('Additional material requests',table(['Request / material','Requested','Issued','Status','Action'],extra.map(r=>`<tr><td>${r.id}<div class="inline-note">${r.item}</div></td><td>${n(r.qty)} kg</td><td>${n(r.issued)} kg</td><td>${pill(r.status)}</td><td>${['Approved','Part issued'].includes(r.status)?btn('Issue','issueExtra',r.id):r.status==='Pending'?'<span class="subtle">Production manager approval</span>':'—'}</td></tr>`)))}</div><div>${card('Material accountability',`<div class="card-body">${[['Actual consumption',j.consumed],['Unused returns',j.returned],['Collected waste',j.waste],['Unrecoverable loss',j.loss],['Still in production / unresolved',round(j.issued-accounted)]].map(([l,v])=>`<div class="stage"><div class="stage-main">${l}</div><b>${n(v)} kg</b></div>`).join('')}<div class="info">Physical input accounting is separate from finished output. Do not add consumed material to output as another stock balance.</div></div>`)}${card('Recipe & version',`<div class="card-body"><b>${esc(j.recipe)}</b><p class="subtle" style="margin-top:8px">Illustrative production specification. Not an approved manufacturing recipe.</p><button class="link" data-action="recipe" data-id="${j.id}">View example recipe →</button></div>`)}${card('Closure checklist',`<div class="card-body"><p class="subtle">Production manager reviews output, consumption, returns, waste and authorised exceptions. Quantity completion alone cannot close a JC.</p><div class="info warning">Closure and reopening are specified in the blueprint; this prototype focuses on partial outputs and approvals.</div></div>`)}</div></div>`;}
function stockPage(){const tabs=`<div class="tabs">${[['stock','Demo stock & lots'],['catalogue','Workbook material master'],['counts','Blind count demonstration']].map(([id,t])=>`<button class="tab ${inventoryTab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}</div>`;let body='';if(inventoryTab==='catalogue'){const mats=source.Material_Master.filter(m=>(m.Material_ID+' '+m.Material_Name).toLowerCase().includes(query.toLowerCase()));body=`<div class="filters"><input id="query" class="search" aria-label="Search materials" placeholder="Search code or material" value="${esc(query)}"><span class="pill source">Workbook source · ${mats.length} records</span></div>`+card('Material master',table(['Material / code','Category','Stock unit','Pack','Cost / kg','Reorder level'],mats.map(m=>`<tr><td>${esc(m.Material_Name)}<div class="code">${m.Material_ID}</div></td><td>${m.Category}</td><td>${m.Base_Unit}</td><td>${m.Pack_Type} · ${n(m.Pack_Size_KG)} kg</td><td>${money(m.Unit_Cost_INR)}</td><td>${n(m.Reorder_Level_KG)} kg</td></tr>`)))+`<div class="info">Source master values are retained for review. Prices, reorder levels and pack conversions are not certified live settings.</div>`;}else if(inventoryTab==='counts'){body=`<div class="info">Switch to Stores operator to submit a blind count. The expected balance is hidden in the count form and revealed after submission. Recount and adjustment controls are described in the blueprint.</div>`+card('Submitted counts',table(['Reference','Batch','Physical count','System at count','Variance','Status'],state.counts.map(c=>`<tr><td>${c.id}</td><td>${c.lot}</td><td>${n(c.actual)} kg</td><td>${n(c.expected)} kg</td><td>${n(c.variance)} kg</td><td>${pill(c.status)}</td></tr>`)),`<button class="btn small" data-action="count">+ Blind count</button>`);}else{const lots=byEntity(state.lots).filter(l=>(l.id+' '+l.name).toLowerCase().includes(query.toLowerCase()));body=`<div class="filters"><input id="query" class="search" aria-label="Search stock" placeholder="Search batch or material" value="${esc(query)}"><span class="subtle">Demonstration quantities · not reconciled opening stock</span></div>`+card('Stock by batch and location',table(['Material / batch','Entity / location','Physical qty','Expiry','Status'],lots.map(l=>`<tr><td>${esc(l.name)}<div class="code">${l.id}</div></td><td>${l.entity}<div class="inline-note">${l.location}</div></td><td>${n(l.qty)} kg</td><td>${l.expiry||'Missing'}</td><td>${pill(stockStatus(l))}</td></tr>`)));}return heading('INVENTORY','Stock with a clear identity.','Material codes, lot custody and restrictions remain visible.')+tabs+body;}
function receivingPage(){return heading('INBOUND','Receive what actually arrived.','Capture custody separately from acceptance, over-delivery and release.',`<button class="btn" data-action="receipt">+ Create GRN</button>`)+card('Example supplier receipts',table(['GRN / PO','Supplier / material','Ordered','Received','Excess','Status'],state.receipts.map(r=>`<tr><td>${r.id}<div class="code">${r.po}</div></td><td>${esc(r.supplier)}<div class="subtle">${esc(r.material)}</div></td><td>${n(r.ordered)} kg</td><td>${n(r.received)} kg</td><td>${n(r.excess)} kg</td><td>${pill(r.status)}</td></tr>`)))+card('Original locations',table(['Code','Entity','Store','Storage condition'],source.Location_Master.map(l=>`<tr><td class="code">${l.Location_ID}</td><td>${l.Branch_Entity}</td><td>${l.Store_Name}</td><td>${l.State_Type}</td></tr>`)),pill('Workbook source','source'))+card('Original internal transfers',table(['Transfer','Material','Route','Quantity','Source status'],source.Internal_Transfers.map(t=>`<tr><td>${t.Transfer_ID}</td><td>${t.Material_Name}</td><td>${t.From_Location} → ${t.To_Location}</td><td>${n(t.Quantity_KG)} kg</td><td>${pill('Unreconciled','amber')}<div class="inline-note">Workbook says ${t.Status}</div></td></tr>`)))+`<div class="info warning">The supplied ledger has no transfer events matching these records. The prototype preserves this gap; it does not invent balancing postings.</div>`;}
function wastePage(){const w=state.waste;return heading('WASTE BANK','Collect. Weigh. Account for it.','Operators handle routine receipts. Managers investigate exceptions.',`<button class="btn" data-action="waste">+ Declare collected waste</button>`)+`<div class="kpis">${kpi('Collected waste on hand',n(w.reduce((a,x)=>a+x.remaining,0))+' kg','Physically received, held for assessment')}${kpi('Awaiting stores receipt',w.filter(x=>x.received===null).length,'Declared waste is not yet bank stock')}${kpi('Receipt differences',w.filter(x=>x.state==='Receipt discrepancy').length,'Store manager investigation')}${kpi('Route capabilities','4','Rework · recycle sale · return · disposal')}</div>`+card('Waste bank register',table(['Receipt / JC','Material / reason','Declared','Received','On hand','State','Action'],w.map(x=>`<tr><td>${x.id}<div class="code">${x.job}</div></td><td>${esc(x.material)}<div class="subtle">${esc(x.reason)}</div></td><td>${n(x.declared)} kg</td><td>${x.received===null?'Pending':n(x.received)+' kg'}</td><td>${n(x.remaining)} kg</td><td>${pill(x.state)}</td><td>${x.received===null?btn('Weigh & receive','receiveWaste',x.id):btn('Route provisions','routes',x.id,true)}</td></tr>`)))+card('Routes stay controlled',`<div class="card-body"><div class="flow">${[['Rework / reuse','Suitability + linked rework JC'],['Recycler sale','Approved buyer + actual dispatch'],['Supplier return','Agreement + dispatch reference'],['Disposal','Evidence + accounts verification']].map(([a,b])=>`<div class="flow-node"><b>${a}</b><small>${b}</small><p style="margin:10px 0 0">${pill('Eligibility not configured','amber')}</p></div>`).join('')}</div><p class="subtle">All four routes are included in the blueprint. None grants permission to reuse or dispose of a material. Unrecoverable spillage is a loss record, not fictitious waste stock.</p></div>`);}
function qualityPage(){const lots=byEntity(state.lots).filter(l=>l.qty>0);return heading('QUALITY','Release is a quality decision.','Inspection, expiry and incident holds stay separate from production progress.')+card('Inspection & hold register',table(['Batch / material','Quantity','Current status','Origin','Action'],lots.map(l=>`<tr><td><span class="code">${l.id}</span><br>${esc(l.name)}</td><td>${n(l.qty)} kg</td><td>${pill(stockStatus(l))}${l.productionVerified===false?'<div class="inline-note">Production verification pending</div>':''}</td><td>${l.job||'Supplier receipt / opening example'}</td><td><div class="actions">${l.productionVerified===false?btn('Verify output','verifyOutput',l.id):''}${!l.recall?btn('Inspect','quality',l.id,true):btn('Incident details','incidentInfo',l.id,true)}${!l.recall&&l.quality==='Released'?btn('Place hold','hold',l.id,true):''}</div></td></tr>`)))+`<div class="info">Only the Quality role can release or reject output. A missing or expired date blocks release. Incident holds cannot be cleared through the normal inspection form.</div>`;}
function financePage(){return heading('SUPPLIER ACCOUNTS','From invoice to confirmed payment.','Illustrative invoices and suppliers · Actual workbook costs stay in the material master.')+`<div class="kpis">${kpi('Example invoices',state.payments.length,'One consolidated invoice view each')}${kpi('Pending approval',state.payments.filter(p=>p.status==='Pending approval').length,'Independent manager / Director review')}${kpi('Confirmed payments',money(state.payments.filter(p=>p.status==='Completed').reduce((a,p)=>a+p.amount,0)),'Only after proof verification')}${kpi('Manager approval limit','₹50 lakh','Per transaction; Director above limit')}</div>`+card('Supplier payment register',table(['Payment / invoice','Supplier','Request amount','Approval route','Status','Next action'],state.payments.map(p=>`<tr><td><button class="link" data-action="invoice" data-id="${p.id}">${p.id}</button><div class="code">${p.invoice}</div></td><td>${esc(p.supplier)}<div class="inline-note">${p.bank}</div></td><td>${money(p.amount)}</td><td>${p.amount>LIMIT?'Director':'Accounts manager'}</td><td>${pill(p.status)}</td><td>${p.status==='Pending approval'?btn('Review approval','paymentApprove',p.id):p.status==='Approved'?btn('Submit to bank','paymentExecute',p.id):p.status==='Submitted to bank'?btn('Record proof','paymentProof',p.id):p.status==='Proof awaiting verification'?btn('Verify & complete','paymentVerify',p.id):pill('Bank confirmed','green')}</td></tr>`)))+`<div class="grid-equal">${card('Advance & invoice reconciliation',`<div class="card-body"><h3>DEMO-INV-101</h3><div class="metric-grid"><div><small>Invoice total</small><b>₹1,00,000</b></div><div><small>Verified advance</small><b>₹20,000</b></div><div><small>Remaining payable</small><b>${money(state.payments[0].status==='Completed'?0:80000)}</b></div></div><p class="subtle" style="margin-top:14px">Pending payment: ${money(state.payments[0].status==='Completed'?0:80000)}. Pending amounts are shown separately, not treated as confirmed payments.</p>${btn('View invoice history','invoice','PAY-001',true)}</div>`)}${card('Payment controls',`<div class="card-body"><div class="activity"><div class="activity-dot"></div><p>Operator prepares; authorised independent role approves.</p></div><div class="activity"><div class="activity-dot"></div><p>Accounts manager executes. Operator enters bank proof.</p></div><div class="activity"><div class="activity-dot"></div><p>Accounts manager verifies completion. Director and accounts manager are notified.</p></div><div class="info warning">Bank submission and email delivery are simulated. No external connection or money movement.</div></div>`)}</div>`;}
function tracePage(){return heading('DISPATCH & TRACEABILITY','Know where every batch went.','Trace inputs to output, then output to customers.',`<button class="btn" data-action="dispatch">+ Record dispatch</button>`)+card('Batch genealogy',`<div class="card-body"><div class="subtle">Demonstration chain · Source inputs → job card → output → dispatch</div><div class="flow"><div class="flow-node"><b>ZAM-2210-A</b><small>Cocoa input lot</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>JC-G-1022-006</b><small>Historical example production</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>G-DC-2210-A</b><small>Dark Chocolate Slab</small></div><span class="flow-arrow">→</span><div class="flow-node"><b>BakeMasters</b><small>40 kg dispatched · DSP-001</small></div></div><p class="inline-note">Genealogy links are illustrative, not inferred from the historical workbook. Historical JC-006 is not part of the active job-card register.</p></div>`)+card('Customer dispatch register',table(['Dispatch','Customer','Output batch','Quantity','Incident'],state.dispatches.map(d=>`<tr><td>${d.id}<div class="inline-note">${d.date}</div></td><td>${esc(d.customer)}</td><td>${d.batch}</td><td>${n(d.qty)} kg</td><td>${d.incident?pill(d.incident,'red'):pill('No active incident','green')}</td></tr>`)))+card('Recall monitoring',table(['Incident / batch','Affected customer','Dispatched','Returned','Unresolved','Owner'],state.dispatches.filter(d=>d.incident).map(d=>`<tr><td>${d.incident}<div class="code">${d.batch}</div></td><td>${esc(d.customer)}</td><td>${n(d.qty)} kg</td><td>${n(d.returned)} kg</td><td>${n(d.qty-d.returned)} kg</td><td>${d.owner}</td></tr>`)),`<button class="link" data-page="quality">Place a quality hold ↗</button>`)+`<div class="info">Quality may contain immediately. Director authorises customer communication or recall; sales contacts customers. This prototype does not send customer messages.</div>`;}
function approvalsPage(){return heading('CONTROL CENTRE','The right decision, by the right role.','Role switching is a demonstration tool, not secure authentication.')+card('Inventory & production requests',table(['Request','Detail','Prepared by','Approver','Status','Action'],state.requests.map(r=>`<tr><td>${r.id}</td><td>${r.type}<div class="subtle">${esc(r.reason)}</div><div class="code">${r.job||r.item} · ${money(r.amount)}</div></td><td>${r.by}</td><td>${r.approver}</td><td>${pill(r.status)}</td><td>${r.status==='Pending'?btn('Approve','approveRequest',r.id):['Approved','Part issued'].includes(r.status)?btn('Issue approved extra','issueExtra',r.id,true):'—'}</td></tr>`)))+card('Current approval matrix',table(['Domain','Manager authority','Director authority'],[['Inventory adjustments','Store manager ≤ ₹50 lakh','Above ₹50 lakh'],['Supplier payments','Accounts manager ≤ ₹50 lakh','Above ₹50 lakh'],['Customer credits','Accounts manager ≤ ₹50 lakh','Above ₹50 lakh'],['Production JC / recipe','Production manager · operational approval','Exceptions as separately defined'],['Quality hold / release','Quality · no monetary bypass','Cannot substitute for quality release']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`)))+`<div class="info">No self-approval or artificial splitting. Requests remain pending if an independent authorised approver is unavailable. Waste routes, non-monetary configuration and some purchasing exceptions still need a validated approval mapping.</div>`;}
function auditPage(){return heading('ACTIVITY','A record of what changed.','Every prototype action retains its role, reference and effect.',`<button class="btn secondary" data-action="export">Export review data</button>`)+`<div class="grid-two"><div>${card('Audit trail',table(['Time / actor','Event','Reference / detail'],state.audit.map(a=>`<tr><td>${esc(a.time)}<div class="inline-note">${esc(a.role)}</div></td><td>${esc(a.action)}</td><td><span class="code">${esc(a.ref)}</span><div class="subtle">${esc(a.detail)}</div></td></tr>`)))}</div><div>${card('Notification centre',`<div class="card-body">${state.notifications.length?state.notifications.map(x=>`<div class="activity notification"><div><p><b>${esc(x.title)}</b></p><small>${esc(x.ref)} · ${esc(x.time)}</small><p class="subtle" style="margin-top:6px">To: ${esc(x.to.join(', '))}</p>${pill(x.channels,'blue')}</div></div>`).join(''):'<div class="empty">Workflow actions will create simulated notifications here.</div>'}</div>`)}</div></div>`;}
function blueprintPage(){return heading('BUILD BLUEPRINT','A real workflow. A clear next build.','The prototype makes the decisions tangible. The blueprint defines the production system.',`<a class="btn secondary" href="blueprint.md" download>Download blueprint ↓</a><button class="btn" data-action="walkthrough">Guided walkthrough</button>`)+`<div class="grid-two"><div>${card('What works in this prototype',`<div class="card-body blueprint"><p>Search the imported material catalogue, follow partial job-card output, request and issue extra material, independently receive waste, inspect and hold batches, approve and complete example payments, dispatch eligible batches and trace affected customers.</p><h3>Source data</h3><p>36 materials, six locations, ten ledger transactions, two transfers and one sales order from your workbook. Source stock is not certified or silently merged into the operating demonstration.</p><h3>Illustrative operating scenario</h3><p>Four job cards, controlled operating lots, two payment requests, example receipts and a waste bank. All names, recipes, test evidence and operating transactions beyond the workbook are hypothetical.</p><h3>Before real production</h3><p>Implement secure sign-in, server-enforced roles and separation, a transactional database, durable audit and evidence storage, notification delivery, concurrent posting controls, financial mappings and tested migration.</p><h3>Not a manufacturing instruction</h3><p>Example recipes and inspection forms illustrate record structure. They must be replaced by validated recipes, test methods, acceptance criteria and appropriate technical review.</p></div>`)}${card('Build stages',table(['Stage','Scope','Completion evidence'],[['01 · Foundation','Identity, entities, material master, units, lots, ledger','Role and balanced posting checks'],['02 · Factory flow','PO/GRN/GIN/MRN, JC, waste, quality, traceability','End-to-end and exception scenarios'],['03 · Finance & control','Matching, advances, credits, bank evidence, recall','Balances, reversals and authority checks'],['04 · Pilot','Verified data, training, reconciliation, backups','Process-owner sign-off and recovery test']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`)))}</div><div>${card('Demonstration roles',`<div class="card-body">${ROLES.map(r=>`<div class="stage"><div class="stage-main"><b>${r}</b></div><button class="link" data-role="${r}">Try role →</button></div>`).join('')}</div>`)}${card('Workspace tools',`<div class="card-body"><p class="subtle">Changes remain in this browser. Export review data to retain your walkthrough results.</p><div class="actions"><button class="btn secondary" data-action="export">Export JSON</button><button class="btn secondary" data-action="reset">Reset examples</button></div></div>`)}</div></div>`;}
// MRS and GIN screens are part of the existing app shell.
let issueTab='mrs',mrsLineCount=1,activeGinToken='';
function issuesPage(){
  const mrs=byEntity(state.requisitions),gins=byEntity(state.gins);
  const tabNames=[['mrs','MRS requests'],['gin','GIN register'],['custody','Production custody'],['ledger','GIN stock events']];
  let body='';
  if(issueTab==='mrs')body=card('Material requisition slips',table(['MRS / job card','Purpose / stage','Materials','Status','Action'],mrs.map(r=>`<tr><td><button class="link" data-action="mrsView" data-id="${r.id}">${r.id}</button><div><button class="link code" data-job="${r.job}">${r.job}</button></div><div class="inline-note">${r.entity}</div></td><td>${esc(r.purpose)}<div class="subtle">${esc(r.stage)}</div></td><td>${r.lines.length} line${r.lines.length===1?'':'s'}<div class="inline-note">${n(r.lines.reduce((a,l)=>a+l.issued,0))} kg issued</div></td><td>${pill(r.status)}</td><td><div class="actions">${r.status==='Pending approval'?btn('Review MRS','mrsReview',r.id):['Approved','Part issued'].includes(r.status)?btn('Create GIN','ginCreate',r.id):btn('View','mrsView',r.id,true)}</div></td></tr>`)));
  if(issueTab==='gin')body=card('Goods issue notes to production',table(['GIN / date','Job / MRS','From → to','Issued','Handover','Action'],gins.map(g=>`<tr><td><button class="link" data-action="ginView" data-id="${g.id}">${g.id}</button><div class="inline-note">${g.date}</div></td><td><button class="link code" data-job="${g.job}">${g.job}</button><div class="code">${g.request}</div></td><td>${g.from} → ${g.to}<div class="inline-note">${g.entity}</div></td><td>${n(g.total)} kg<div class="inline-note">${g.lines.length} lot allocation${g.lines.length===1?'':'s'}</div></td><td>${esc(g.handedTo)}<div class="inline-note">Issued by ${esc(g.issuedBy)}</div></td><td>${btn('View / print','ginView',g.id,true)}</td></tr>`)));
  if(issueTab==='custody')body=card('Production custody from new GINs',table(['Job card','Material / lot','Production location','Quantity'],byEntity(state.productionCustody).map(c=>`<tr><td><button class="link code" data-job="${c.job}">${c.job}</button></td><td>${esc(material(c.item)?.Material_Name||c.name)}<div class="code">${c.lot}</div></td><td>${c.location}<div class="inline-note">${c.entity}</div></td><td>${n(c.qty)} ${c.unit}</td></tr>`)))+'<div class="info">This view tracks new GIN handovers in this update, not a reconstruction of earlier example issues. Issuing to production is a custody transfer, not consumption. Later usage and returns require their own records.</div>';
  if(issueTab==='ledger')body=card('Balanced GIN event ledger',table(['Event / GIN','Job / request','Material / lot','Location','Movement'],byEntity(state.issueLedger).map(e=>`<tr><td class="code">${e.id}<div><button class="link" data-action="ginView" data-id="${e.gin}">${e.gin}</button></div></td><td class="code">${e.job}<div>${e.request}</div></td><td>${e.item}<div class="code">${e.lot}</div></td><td>${e.location}<div class="inline-note">${e.kind}</div></td><td>${e.quantity>0?'+':''}${n(e.quantity)} ${e.unit}</td></tr>`)))+'<div class="info">Each GIN allocation has equal stores-out and production-in events. Company physical quantity stays unchanged by the handover.</div>';
  return heading('MATERIAL FLOW / JOB CARD','Request it. Issue it. Trace it.','MRS = production material request. GIN = actual issue to the floor. GRN = supplier receipt.',`<button class="btn secondary" data-action="ginCreate">+ Create GIN</button><button class="btn" data-action="mrsCreate">+ Create MRS</button>`)+`<div class="kpis">${kpi('Pending MRS approval',mrs.filter(r=>r.status==='Pending approval').length,'Production manager review')}${kpi('Approved / part-issued MRS',mrs.filter(r=>['Approved','Part issued'].includes(r.status)).length,'Outstanding approved material')}${kpi('GINs posted',gins.length,'Each physical issue has a numbered document')}${kpi('Issued through new GINs',n(gins.reduce((a,g)=>a+g.total,0))+' kg','Transferred to production, not consumed')}</div><div class="tabs">${tabNames.map(([id,t])=>`<button class="tab ${issueTab===id?'active':''}" data-action="issueTab" data-id="${id}">${t}</button>`).join('')}</div>${body}<div class="info">Use Production operator to create MRS → Production manager to approve → Stores operator to post GIN. Materials, stores and job entity must match. Held or expired lots cannot be issued. <button class="link" data-page="receiving">Supplier GRN creation is in Receipts & transfers →</button></div>`;
}
function jobIssuesSection(j){
  const requests=state.requisitions.filter(r=>r.job===j.id),gins=state.gins.filter(g=>g.job===j.id);
  return card('MRS and GIN documents for this job',table(['Document','Material / quantity','State / reference','Action'],[...requests.map(r=>`<tr><td>${r.id}</td><td>${r.lines.length} materials</td><td>${pill(r.status)}</td><td>${btn('View MRS','mrsView',r.id,true)}</td></tr>`),...gins.map(g=>`<tr><td>${g.id}</td><td>${n(g.total)} kg</td><td>${g.request} · ${g.from} → ${g.to}</td><td>${btn('View GIN','ginView',g.id,true)}</td></tr>`)]),`<div class="actions">${btn('Create MRS','mrsCreate',j.id,true)}<button class="link" data-page="issues">All MRS & GIN →</button></div>`);
}
function mrsLineRow(i){return `<div class="mrs-line" data-line="${i}"><div class="field-row">${select('item'+i,'Material '+(i+1),[['','Choose material'],...source.Material_Master.filter(m=>m.Category==='Raw Material'&&m.Status==='Active').map(m=>[m.Material_ID,m.Material_ID+' · '+m.Material_Name])])}${input('quantity'+i,'Requested quantity · kg','number','','min="0.001" step="0.001"')}</div></div>`;}
function requestLines(r){return table(['Material','Requested','Approved','Already issued','Remaining'],r.lines.map(l=>`<tr><td>${esc(l.name)}<div class="code">${l.item}</div></td><td>${n(l.requested)} kg</td><td>${n(l.approved)} kg</td><td>${n(l.issued)} kg</td><td>${n(Math.max(0,l.approved-l.issued))} kg</td></tr>`));}
function mrsInfo(r){return `<p><b>${r.id}</b> · ${pill(r.status)}</p><p class="code">${r.job} · ${esc(r.entity)} · ${esc(r.stage)}</p><p>${esc(r.reason)}</p>${requestLines(r)}<p class="subtle" style="margin-top:12px">Requested by ${esc(r.requestedBy)}${r.approvedBy?' · Reviewed by '+esc(r.approvedBy):''}. The request and its approval do not move stock.</p>`;}
function ginForm(mrsId='',extraId=''){
  const r=mrsId?state.requisitions.find(r=>r.id===mrsId):state.requests.find(r=>r.id===extraId),j=state.jobs.find(j=>j.id===r?.job);
  if(!r||!j)return infoModal('Select an approved request','<p>An approved MRS or approved extra-material request is required before stores can issue material.</p>');
  const rows=mrsId?r.lines.filter(l=>l.approved>l.issued):[{id:r.id,item:r.item,name:material(r.item)?.Material_Name||r.item,approved:r.qty,issued:r.issued}];
  const stores=source.Location_Master.filter(l=>l.Branch_Entity===j.entity+' Food Products'&&l.Store_Type==='Raw Material');
  activeGinToken=globalThis.crypto?.randomUUID?.()||('gin-'+Date.now()+'-'+Math.random().toString(36).slice(2));
  const date=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});
  formModal('Create GIN · actual issue to production',`<p><b>${esc(r.id)}</b> · ${esc(j.id)} · ${esc(j.entity)}</p><div class="field-row">${input('date','Actual issue date','date',date,'required')}${select('location','Issuing store',stores.map(l=>[l.Location_ID,l.Location_ID+' · '+l.Store_Name]))}</div>${select('destination','Receiving production floor',[[j.entity==='Goldsmith'?'G-PROD':'C-PROD',j.entity+' production floor · demonstration location']])}${input('handedTo','Handed to · production receiver','text','','required')}<h3>Actual quantities to issue</h3><p class="subtle">Enter a partial quantity or 0 to skip a material. FEFO selects eligible lots within the issuing store.</p>${rows.map((l,i)=>`<div class="field"><label for="f-issue${i}">${esc(l.name)} · ${esc(l.item)} · ${n(l.approved-l.issued)} kg approved and outstanding</label><input id="f-issue${i}" name="issue${i}" type="number" min="0" max="${l.approved-l.issued}" step="0.001" value="${l.approved-l.issued}"></div>`).join('')}${input('remarks','Handover remarks (optional)')}<div class="info">Posting creates one numbered GIN and balanced stores-out / production-in records. Holds, expiry, approval and available quantities are rechecked before posting. No stock moves until you post.</div>`,'Post GIN',p=>{const lines=rows.map((l,i)=>({line:l.id,quantity:p['issue'+i]})).filter(l=>Number(l.quantity)>0);if(run('postGin',{...p,mrs:mrsId,extra:extraId,lines,token:activeGinToken,locations:source.Location_Master})){page='issues';issueTab='gin';render();}});
}
function issueForms(a,id){
  if(!['issueTab','mrsCreate','mrsAddLine','mrsView','mrsReview','ginCreate','ginSelectMrs','ginView','printGin','issueExtra'].includes(a))return false;
  if(a==='issueTab'){issueTab=id;page='issues';render();return true;}
  if(a==='mrsAddLine'){if(mrsLineCount>=20){toast('A maximum of 20 materials per requisition is supported.');return true;}$('#mrs-lines').insertAdjacentHTML('beforeend',mrsLineRow(mrsLineCount++));return true;}
  if(a==='mrsCreate'){
    mrsLineCount=1;
    formModal('Create MRS · material requisition for a job',select('job','Job card',openJobs(),id)+input('stage','Production stage','text','Mixing','required')+select('purpose','Request purpose',['Planned production','Additional material'])+input('needed','Required date','date',new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),'required')+reason('Reason / production requirement')+`<h3>Materials required</h3><div id="mrs-lines">${mrsLineRow(0)}</div><button type="button" class="btn secondary small" data-action="mrsAddLine">+ Add material</button><div class="info">Submit as Production operator. Production manager approval comes before stores creates a GIN. MRS submission does not reduce stock.</div>`,'Submit MRS',p=>{const lines=[];for(let i=0;i<mrsLineCount;i++){if(p['item'+i]||p['quantity'+i])lines.push({item:p['item'+i],quantity:p['quantity'+i]});}if(run('createMrs',{...p,lines,materials:source.Material_Master})){page='issues';issueTab='mrs';render();}});return true;
  }
  if(a==='mrsView'){const r=state.requisitions.find(x=>x.id===id);if(r)infoModal('MRS details',mrsInfo(r));return true;}
  if(a==='mrsReview'){const r=state.requisitions.find(x=>x.id===id);if(r)formModal('Production manager review',mrsInfo(r)+select('decision','Decision',['Approve','Reject'])+input('note','Review note','text','','required'),'Save decision',p=>run('reviewMrs',{...p,id}));return true;}
  if(a==='ginCreate'){
    if(id){ginForm(id);return true;}const approved=state.requisitions.filter(r=>['Approved','Part issued'].includes(r.status)&&state.jobs.some(j=>j.id===r.job&&!j.closed));
    if(!approved.length){infoModal('No approved MRS awaiting issue','<p>Create an MRS as Production operator and approve it as Production manager first.</p><button class="btn secondary" type="button" data-action="mrsCreate">Create MRS</button>');return true;}
    formModal('Select MRS for goods issue',select('mrs','Approved MRS',approved.map(r=>[r.id,r.id+' · '+r.job+' · '+r.entity])),'Continue',p=>ginForm(p.mrs));return true;
  }
  if(a==='issueExtra'){ginForm('',id);return true;}
  if(a==='ginView'){
    const g=state.gins.find(x=>x.id===id);if(!g)return true;
    infoModal('Goods issue note · '+g.id,`<div class="gin-document"><h3>${g.id} · Posted</h3><p>${esc(g.entity)} · Issue date ${esc(g.date)}</p><p><b>Job card:</b> ${esc(g.job)}<br><b>Request:</b> ${esc(g.request)}<br><b>Stage:</b> ${esc(g.stage)}<br><b>From:</b> ${esc(g.from)} → <b>To:</b> ${esc(g.to)}</p>${table(['Material','Batch / lot','Expiry','Actual issue'],g.lines.map(l=>`<tr><td>${esc(material(l.item)?.Material_Name||l.name)}<div class="code">${l.item}</div></td><td>${l.lot}</td><td>${l.expiry||'Not applicable'}</td><td>${n(l.quantity)} ${l.unit}</td></tr>`))}<p style="margin-top:15px"><b>Total:</b> ${n(g.total)} kg</p><p><b>Issued by:</b> ${esc(g.issuedBy)}<br><b>Handed to:</b> ${esc(g.handedTo)}<br><b>Request approved by:</b> ${esc(g.approvedBy)}</p><p>${esc(g.reason)}</p><p class="inline-note">${esc(g.created)} · Browser-local demonstration document</p></div><button class="btn secondary no-print" type="button" data-action="printGin">Print GIN</button>`);return true;
  }
  if(a==='printGin'){document.body.classList.add('printing-gin');window.addEventListener('afterprint',()=>document.body.classList.remove('printing-gin'),{once:true});window.print();return true;}
  return true;
}

function render(){const pages={overview,jobs:jobsPage,issues:issuesPage,stock:stockPage,receiving:receivingPage,waste:wastePage,quality:qualityPage,finance:financePage,trace:tracePage,approvals:approvalsPage,audit:auditPage,blueprint:blueprintPage};$('#app').innerHTML=shell((pages[page]||overview)());}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';}
const input=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const select=(name,label,items,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}">${items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`;
const reason=(label='Reason')=>`<div class="field"><label for="f-reason">${label}</label><textarea id="f-reason" name="reason" required></textarea></div>`;
const openJobs=()=>state.jobs.filter(j=>!j.closed).map(j=>[j.id,j.id+' · '+j.product]);
function formModal(title,body,submit,onSubmit){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${title}</h2><button data-action="close" aria-label="Close dialog">×</button></header><form id="dialog-form">${body}<div id="form-error" class="error" role="alert"></div><footer><button type="button" class="btn secondary" data-action="close">Cancel</button>${submit?`<button class="btn" type="submit">${submit}</button>`:''}</footer></form></section></div>`;document.body.style.overflow='hidden';$('#dialog-form').onsubmit=e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.target)));};const el=$('#dialog-form input, #dialog-form select, #dialog-form textarea');if(el)el.focus();}
function infoModal(title,body){formModal(title,body,'',()=>{});}
function action(a,id){if(issueForms(a,id))return;if(a==='close')return closeModal();if(a==='menu'){menu=!menu;return render();}if(a==='sourceTransfers'){page='receiving';return render();}if(a==='output')return formModal('Record job-card output',`<p class="subtle">Production operator records; production manager verifies; quality releases. Example expiry, not a shelf-life specification.</p>${select('job','Job card',openJobs(),id)}<div class="field-row">${select('stage','Output stage',['Finished','Semi-finished'])}${input('qty','Actual output · kg','number','', 'min="0.001" step="0.001" required')}</div>${input('expiry','Expiry date · example only','date','2027-04-24','required')}<div class="info">A new batch is created and placed on hold. No automatic quality release.</div>`,'Record output',p=>run('output',p));
if(a==='extra')return formModal('Request additional material',select('job','Job card',openJobs(),id)+select('item','Material',source.Material_Master.filter(m=>m.Category==='Raw Material').map(m=>[m.Material_ID,m.Material_ID+' · '+m.Material_Name]))+input('qty','Extra quantity · kg','number','','min="0.001" step="0.001" required')+reason()+'<div class="info">Production manager approval is required before stores issue.</div>','Submit request',p=>run('requestExtra',{...p,cost:material(p.item)?.Unit_Cost_INR}));
if(a==='approveRequest')return formModal('Review request',(()=>{const r=state.requests.find(x=>x.id===id);return `<p><b>${r.id} · ${r.type}</b></p><p>${esc(r.reason)}</p><p class="subtle">Prepared by ${r.by} · Required approver: ${r.approver}</p><div class="info">${r.type==='Stock adjustment'?'Approval immediately posts the demonstrated correction once.':'Approval does not issue stock. Stores records actual issue separately.'}</div>`;})(),'Approve',()=>run('approveRequest',{id}));
if(a==='waste')return formModal('Declare collected waste',select('job','Source job card',openJobs())+input('material','Waste description','text','Chocolate process residue','required')+input('qty','Physically collected · kg','number','','min="0.001" step="0.001" required')+reason()+'<div class="info">Unrecoverable spillage belongs in a loss record. Only collected material goes to the waste bank.</div>','Declare waste',p=>run('waste',p));
if(a==='receiveWaste'){const w=state.waste.find(x=>x.id===id);return formModal('Weigh and receive waste',`<p>${w.id} · ${esc(w.material)}</p><p class="subtle">Production declared ${n(w.declared)} kg. Retain actual receiving weight separately.</p>`+input('qty','Actual measured receipt · kg','number','','min="0.001" step="0.001" required'),'Receive into hold',p=>run('receiveWaste',{...p,id}));}
if(a==='routes')return infoModal('Waste route provisions',`<p>Rework or reuse, recycler sale, supplier return and disposal are supported in the design.</p><div class="info warning">The eligible waste classes, technical checks and route authorities are not configured. This receipt stays held; no action is silently approved.</div><p class="subtle">The blueprint describes each route and its ledger and evidence requirements.</p><a href="blueprint.md" download>Download blueprint</a>`);
if(a==='verifyOutput')return run('verifyOutput',{id});
if(a==='quality')return formModal('Record quality decision',`<p><b>${esc(id)}</b></p><p class="subtle">Use a hypothetical evidence reference such as DEMO-QC-024. This form does not define a real food-quality test.</p>`+'<div class="info">Example checklist: batch and job-card identity match; packaging and visual condition checked; expiry and label checked; required specialist tests reviewed. These are illustrative record prompts, not validated acceptance criteria.</div>'+select('checklist','Recorded inspection checklist result',['Passed','Failed'])+select('decision','Decision',['Release','Reject'])+input('evidence','Inspection / evidence reference','text','','required')+'<div class="info">Only Quality can decide. Production verification, expiry and active incident restrictions are checked.</div>','Save quality decision',p=>run('quality',{...p,id}));
if(a==='hold')return formModal('Place immediate quality hold',`<p><b>${esc(id)}</b></p>`+reason('Quality concern / hold reason')+'<div class="info warning">Further dispatch stops immediately. Director, production manager and store manager receive simulated system and email alerts.</div>','Apply hold',p=>run('hold',{...p,id}));
if(a==='incidentInfo'){const l=state.lots.find(x=>x.id===id);return infoModal('Active quality incident',`<p><b>${esc(l.incident)}</b> · ${esc(l.id)}</p><p>${esc(l.incidentReason)}</p><div class="info warning">Release requires a separate quality investigation and evidence. Recall closure is not stock release. This prototype does not provide a shortcut to clear the incident.</div><button type="button" class="btn secondary" data-action="closeTrace">Open dispatch trace →</button>`);}
if(a==='closeTrace'){closeModal();return navigate('trace');}
if(a==='paymentApprove'){const p=state.payments.find(x=>x.id===id);return formModal('Approve supplier payment',`<p><b>${p.id} · ${esc(p.supplier)}</b></p><p>${money(p.amount)} · ${p.invoice}</p><p class="subtle">Prepared by ${p.by}. Required role: ${p.amount>LIMIT?'Director':'Accounts manager'}.</p><div class="info">This records business approval only. No bank transfer occurs.</div>`,'Approve payment',()=>run('paymentApprove',{id}));}
if(a==='paymentExecute')return formModal('Simulate bank submission','<p>The accounts manager submits the approved payment in this demonstration.</p><div class="info warning">No bank connection or money movement. Operator proof entry and manager verification are required next.</div>','Simulate submission',()=>run('paymentExecute',{id}));
if(a==='paymentProof')return formModal('Record bank confirmation proof',input('ref','Example bank reference','text','DEMO-UTR-'+id,'required')+input('evidence','Evidence document reference','text','DEMO-BANK-CONFIRMATION.pdf','required')+'<p class="subtle">Reference-only demonstration. No document is uploaded or bank status verified externally.</p>','Submit proof reference',p=>run('paymentProof',{...p,id}));
if(a==='paymentVerify')return formModal('Verify bank proof',(()=>{const p=state.payments.find(x=>x.id===id);return `<p><b>${esc(p.bankRef)}</b></p><p>${esc(p.evidence)}</p><p class="subtle">Confirm the illustrated proof matches the approved amount and supplier before marking complete.</p>`;})(),'Verify and complete',()=>run('paymentVerify',{id}));
if(a==='invoice'){const p=state.payments.find(x=>x.id===id);return infoModal('Invoice reconciliation · '+p.invoice,table(['Entry','Reference','Amount','Status'],[`<tr><td>Invoice</td><td>${p.invoice}</td><td>${money(p.invoiceTotal)}</td><td>Example verified invoice</td></tr>`,...(p.advance?[`<tr><td>Advance allocation</td><td>ADV-DEMO-001</td><td>${money(p.advance)}</td><td>Verified allocation</td></tr>`]:[]),`<tr><td>Payment</td><td>${p.id}</td><td>${money(p.amount)}</td><td>${p.status}</td></tr>`,`<tr><td><b>Remaining payable</b></td><td>Excludes pending payments</td><td><b>${money(p.invoiceTotal-p.advance-(p.status==='Completed'?p.amount:0))}</b></td><td>Confirmed balance</td></tr>`])+`<div class="info">One invoice record, multiple linked entries. A pending payment alone does not prevent a further legitimate request.</div>`);}
if(a==='dispatch')return formModal('Record finished-goods dispatch',select('lot','Output batch',state.lots.filter(l=>l.stage==='Finished').map(l=>[l.id,l.id+' · '+stockStatus(l)]))+input('customer','Customer','text','BakeMasters · demonstration','required')+input('qty','Actual dispatch · kg','number','','min="0.001" step="0.001" required')+'<div class="info">Held, unreleased, expired and count-discrepant batches cannot be dispatched.</div>','Record dispatch',p=>run('dispatch',p));
if(a==='count')return formModal('Blind stock count',select('lot','Material / batch',state.lots.filter(l=>l.qty>0).map(l=>[l.id,l.id+' · '+l.name]))+input('qty','Physical quantity · kg','number','','min="0" step="0.001" required')+'<div class="info">Expected quantity is not displayed in this form. A difference applies a discrepancy issue block; this form does not post an adjustment. In live use, the manager-controlled count pause precedes counting.</div>','Submit blind count',p=>run('count',p));
if(a==='receipt')return formModal('Receive supplier goods',input('supplier','Supplier · example','text','Meridian Ingredients · example','required')+input('po','Approved PO reference','text','PO-DEMO-042','required')+select('item','Material',source.Material_Master.filter(m=>m.Category==='Raw Material').map(m=>[m.Material_ID,m.Material_Name]))+select('entity','Receiving entity',['Goldsmith','Chocosmith'])+`<div class="field-row">${input('ordered','Outstanding PO quantity · kg','number','100','min="0.001" step="0.001" required')}${input('qty','Actual received · kg','number','100','min="0.001" step="0.001" required')}</div>`+input('expiry','Recorded expiry · leave blank if missing','date','')+'<div class="info">All new receipts are held. Over-delivery creates a receipt exception and cannot use normal release as a bypass.</div>','Record actual receipt',p=>run('receipt',{...p,master:material(p.item)}));
if(a==='recipe')return infoModal('Illustrative recipe · not for manufacturing',`<div class="info warning">Hypothetical example to demonstrate structure. Not a verified formulation or product instruction.</div>`+table(['Material','Example requirement'],[['Sugar M-30','517 kg'],['Choco Champ Alfa','222.86 kg'],['Zama Alkalized Cocoa 450','16.5 kg'],['Skimmed milk powder','110 kg'],['Specialty fat','233.64 kg']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`))+'<p class="subtle" style="margin-top:15px">Illustrative 1,100 kg input basis. Operator prepares; specialist reviews when needed; production manager approves. Replace with validated process data.</p>');
if(a==='walkthrough')return infoModal('A 10-minute factory walkthrough',`<ol style="padding-left:20px;line-height:1.9;font-size:13px"><li><b>Production operator:</b> create an MRS for an open JC in MRS & GIN. <b>Production manager:</b> approve it. <b>Stores operator:</b> create a partial GIN, then view its lots and production custody.</li><li><b>Production operator:</b> open JC-001 and record 100 kg finished output.</li><li><b>Production manager:</b> verify that new output in Quality & holds.</li><li><b>Quality:</b> release the batch with an example evidence reference.</li><li><b>Stores operator:</b> dispatch a small quantity from the released batch.</li><li><b>Quality:</b> place a hold on that batch. Open Dispatch & traceability to see the affected customer.</li><li><b>Production operator:</b> declare collected waste. Switch to Stores operator to weigh and receive it.</li><li><b>Accounts manager:</b> approve PAY-001 and simulate bank submission.</li><li><b>Accounts operator:</b> record proof. Switch back to Accounts manager to verify completion.</li><li>Try PAY-002: its ₹52 lakh value requires <b>Director</b> approval.</li><li>Review Activity & notifications and export the review data.</li></ol><div class="info">Use the role selector at the top. This is a workflow simulator, not actual sign-in.</div>`);
if(a==='export'){const blob=new Blob([JSON.stringify({label:'Hypothetical prototype review export',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const link=document.createElement('a');link.href=u;link.download='goldsmith-prototype-review.json';link.click();URL.revokeObjectURL(u);return toast('Review data exported.');}
if(a==='reset')return formModal('Reset demonstration workspace','<p>This clears your browser-local walkthrough changes and restores the original examples. Your source workbook is untouched.</p>','Reset examples',()=>{state=seed(source);save();closeModal();render();toast('Demonstration examples restored.');});
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-job],[data-action],[data-tab],[data-role]');if(!el)return;if(el.dataset.page)return navigate(el.dataset.page);if(el.dataset.job)return navigate('jobs',el.dataset.job);if(el.dataset.role){state.role=el.dataset.role;save();render();return;}if(el.dataset.tab){inventoryTab=el.dataset.tab;query='';return render();}if(el.dataset.action)action(el.dataset.action,el.dataset.id||'');});
document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;save();render();}if(e.target.id==='branch'){state.branch=e.target.value;save();render();}if(e.target.id==='filter'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='query'){const pos=e.target.selectionStart;query=e.target.value;render();$('#query')?.focus();$('#query')?.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const nodes=[...$('#modal-root .modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();


